import app from '@adonisjs/core/services/app'
import type { HttpContext } from '@adonisjs/core/http'
import { readFile } from 'node:fs/promises'

/**
 * The OpenAPI document from `node ace docs:generate`, re-generated by the dev server
 * whenever the routes change (see the hooks in adonisrc.ts)
 */
export const OPENAPI_FILE = '.adonisjs/openapi.json'

export default class DocsController {
  /**
   * GET /docs: Scalar UI over /docs.json
   */
  async show({ response }: HttpContext) {
    response.header('Content-Type', 'text/html; charset=utf-8')
    return `<!doctype html>
<html>
  <head>
    <title>GeoPlatform API</title>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
  </head>
  <body>
    <script id="api-reference" data-url="/docs.json"></script>
    <script src="https://cdn.jsdelivr.net/npm/@scalar/api-reference@1.67.0"></script>
  </body>
</html>`
  }

  /**
   * GET /docs.json
   */
  async json({ response }: HttpContext) {
    try {
      const document = await readFile(app.makePath(OPENAPI_FILE), 'utf-8')
      response.header('Content-Type', 'application/json')
      return document
    } catch {
      return response.notFound({ message: 'Run "node ace docs:generate" first' })
    }
  }
}
